/*
  Concepts: Cardiomyopathies (same shape as data/diseases-endocrine.js).

  Each entry is a mechanism, not a disease: idea → cause/effect chain →
  bedside relevance → common traps, with a prediction-style question bank.
  Sources: source-material/cardio-part-1/text/cardiomyopathies.md (plus the
  H&P, physiology, and valvular lectures for bedside links). Anything the
  slides only imply is labeled "Clarification (standard physiology)" in the html.

  Question ids are "<concept id>|<index>" and progress is saved against them:
  only APPEND questions to a concept; never insert, delete, or reorder.
  `correct` is zero-based; the engine shuffles answer order every time.
*/
(function () {
  "use strict";

  var H = window.DiseaseContent;
  var Tbl = H.Tbl, HY = H.HY, Mn = H.Mn, S = H.S, Q = H.Q, D = H.D, L = H.L;

  function chain(steps) {
    return '<ol class="concept-chain">' + steps.map(function (step) { return "<li>" + step + "</li>"; }).join("") + "</ol>";
  }
  function clar(text) {
    return "<p><strong>Clarification (standard physiology):</strong> " + text + "</p>";
  }
  function traps(items) {
    return "<ul>" + items.map(function (item) { return "<li>" + item + "</li>"; }).join("") + "</ul>";
  }

  window.CARDIO_CONCEPTS_CARDIOMYOPATHIES = L("cardiomyopathies", "Cardiomyopathies", [

    // ------------------------------------------------------------------
    D("cmp-squeeze-vs-fill", "Can't squeeze vs can't fill", "Every cardiomyopathy fails in one of two ways: a weak, dilated ventricle that cannot squeeze (systolic dysfunction, low EF) or a thick or stiff ventricle that cannot fill (diastolic dysfunction, EF usually preserved).", [
      S("idea", "The idea", "<p>A ventricle has two jobs each beat: <strong>fill</strong> in diastole and <strong>squeeze</strong> in systole. A cardiomyopathy breaks one of these jobs, and the echo tells you which.</p><p><strong>Dilated CM (DCM)</strong> is a <strong>squeeze</strong> problem. The ventricle is big and baggy, its walls are normal or thin, and it pumps out only a small fraction of what it holds: <strong>systolic dysfunction, EF ≤ 40%</strong>.</p><p><strong>Hypertrophic CM (HCM)</strong> and <strong>restrictive CM (RCM)</strong> are <strong>fill</strong> problems. In HCM the wall is <strong>thick</strong>; in RCM the wall is usually normal thickness but <strong>rigid</strong>. Either way the ventricle resists filling: <strong>diastolic dysfunction</strong>, while LV systolic function is usually preserved.</p><p>Think of a balloon: DCM is an overstretched balloon that won't snap back; HCM/RCM is a thick rubber balloon that is hard to blow up.</p>"),
      S("chain", "Cause → effect", chain([
        "Myocardium changes shape, size, or thickness (the CM phenotype).",
        "Thin, dilated, weak walls → reduced inward systolic motion → low ejection fraction (systolic dysfunction).",
        "Thick (HCM) or stiff (RCM) walls → impaired relaxation → harder to fill (diastolic dysfunction).",
        "Either way, less blood is delivered forward and pressure backs up behind the ventricle.",
        "Final common pathway: heart failure, arrhythmias, and death."
      ]) + Tbl(["Echo pattern", "Ventricle", "Wall", "Main failure", "EF"], [
        ["<strong>DCM</strong>", "Dilated LV cavity", "Normal or ↓ thickness", "Systolic (can't squeeze)", "<strong>≤ 40%</strong>"],
        ["<strong>HCM</strong>", "Not dilated", "<strong>Asymmetric ↑</strong> (≥ 15 mm), usually septal", "Diastolic (can't fill) ± LVOT obstruction", "Usually preserved"],
        ["<strong>RCM</strong>", "Not dilated", "Usually normal, but rigid", "Severe diastolic; restrictive filling", "Usually preserved until severe"],
        ["<strong>ARVC</strong>", "Dilated RV, normal LV (early)", "Fibro-fatty RV wall", "RV failure + VT", "LV normal early"]
      ]) + HY("Big thin ventricle with low EF = DCM (squeeze problem). Thick or stiff ventricle with preserved EF = HCM/RCM (fill problem).")),
      S("bedside", "Why it matters clinically", "<p>The lecture's overall objective is to <strong>correlate the echo findings with the likely type of cardiomyopathy</strong> — this table is that skill. Echo is the test of choice for every type because it shows both anatomy and function.</p><p>The extra heart sound also follows the failure type: <strong>S3</strong> (“Kentucky”) is the gallop of the <strong>dilated</strong> heart; <strong>S4</strong> (“Tennessee”) is blood forced into a <strong>stiff or hypertrophic</strong> ventricle.</p><p>Treatment differs too: a weak DCM ventricle gets afterload reduction (ACE inhibitors), nitrates, diuretics, and even digoxin, while an obstructed HCM ventricle must <em>avoid</em> those same drugs (see the LVOT concepts).</p>"),
      S("traps", "Common traps", traps([
        "<strong>“Heart failure always means a low EF.”</strong> HCM and RCM cause heart failure with usually preserved systolic function — the problem is filling.",
        "<strong>“A big heart on CXR means DCM.”</strong> RCM can also show cardiomegaly, but from <strong>enlarged atria</strong>, not dilated ventricles.",
        "<strong>“Thick wall = strong heart.”</strong> In HCM the thick wall loses elasticity and relaxes poorly; thickness is the problem, not a strength.",
        "<strong>“Peripartum CM is its own echo pattern.”</strong> PPCM typically presents like a dilated CM: LV systolic dysfunction (EF ≤ 45%) with a frequently dilated LV."
      ]))
    ], [
      Q("idea", "Echo shows a dilated LV with thin walls and an EF of 30%. Which failure type is this?", ["Systolic dysfunction — the ventricle can't squeeze (DCM pattern)", "Diastolic dysfunction — the ventricle can't fill (RCM pattern)", "Dynamic outflow obstruction (HCM pattern)", "Isolated right ventricular failure (ARVC pattern)"], 0, "A dilated cavity with normal or thin walls and EF ≤ 40% is the DCM pattern of systolic dysfunction."),
      Q("chain", "The LV wall becomes thicker and loses elasticity. What happens first to ventricular filling?", ["Filling becomes harder because the wall relaxes poorly (diastolic dysfunction)", "Filling becomes easier because the wall is stronger", "Ejection fraction falls below 40% immediately", "The ventricle dilates to hold more blood"], 0, "Thick, inelastic walls impair relaxation, so the ventricle is harder to fill — the HCM definition of diastolic dysfunction."),
      Q("chain", "Echo shows non-dilated, non-hypertrophied ventricles, both atria enlarged, and normal LV systolic function. Which type fits?", ["Restrictive cardiomyopathy", "Dilated cardiomyopathy", "Hypertrophic cardiomyopathy", "Arrhythmogenic right ventricular cardiomyopathy"], 0, "Stiff ventricles of normal size and thickness fill against high pressure, which dilates the atria; systolic function is preserved — the RCM pattern."),
      Q("chain", "Which extra heart sound would you predict in a patient whose problem is a stiff, thick ventricle?", ["S4 — blood forced into a stiff or hypertrophic ventricle", "S3 — volume overload of a dilated ventricle", "An opening snap", "A pericardial knock"], 0, "S4 is produced by atrial contraction forcing blood into a stiff or hypertrophic ventricle; it is the HCM gallop."),
      Q("bedside", "A patient with an EF of 25% is on digoxin, an ACE inhibitor, and furosemide. Which cardiomyopathy pattern does this regimen fit?", ["Dilated — a weak ventricle that benefits from inotropy and afterload/fluid reduction", "Hypertrophic with LVOT obstruction", "Restrictive with preserved EF", "Tako-tsubo after recovery"], 0, "DCM is a squeeze problem, so a positive inotrope (digoxin) and afterload/fluid reduction help; the same drugs are avoided in obstructive HCM."),
      Q("traps", "A CXR shows cardiomegaly but echo shows normal-sized ventricles. What explains the large silhouette in RCM?", ["Enlarged atria from high filling pressures", "Dilated ventricles from systolic failure", "Asymmetric septal hypertrophy", "Fibro-fatty replacement of the RV"], 0, "In RCM the ventricles are non-dilated; cardiomegaly on CXR is secondary to the enlarged atria."),
      Q("idea", "What is the final common pathway of the various cardiomyopathy types?", ["Heart failure, arrhythmias, and death", "Spontaneous recovery in all types", "Isolated valve stenosis", "Systemic hypertension"], 0, "Whatever the phenotype, cardiomyopathies usually end in heart failure, arrhythmias, and death."),
      Q("traps", "A peripartum patient has an LVEF of 35% and a dilated LV. Which failure type does PPCM most resemble?", ["Dilated cardiomyopathy — systolic dysfunction", "Hypertrophic cardiomyopathy — diastolic dysfunction", "Restrictive cardiomyopathy — stiff ventricles", "ARVC — right ventricular fibro-fatty change"], 0, "PPCM is LV systolic dysfunction (EF ≤ 45%) with a frequently dilated LV; it presents like a dilated cardiomyopathy.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-backward-pressure", "Heart failure progression: from no reserve to backed-up fluid", "A failing ventricle first shows itself only when demand rises (exertion); later, fluid retention raises filling pressures and blood backs up — into the lungs from the left heart, into the veins from the right heart.", [
      S("idea", "The idea", "<p>A healthy heart has <strong>reserve</strong>: it can speed up and squeeze harder when you exercise. A cardiomyopathy eats into that reserve first, so the earliest symptoms appear only with <strong>exertion</strong> — DOE, fatigue, dizziness, syncope, chest pain. These are vague and easy to blame on aging or deconditioning.</p><p>Over time (or rapidly in acute HF), <strong>fluid retention</strong> raises the <strong>filling pressures</strong> inside the heart. Pressure that can't move forward moves <strong>backward</strong>:</p><ul><li>Behind the <strong>left</strong> heart are the <strong>lungs</strong> → pulmonary congestion.</li><li>Behind the <strong>right</strong> heart are the <strong>systemic veins</strong> → neck veins, legs, abdomen.</li></ul>"),
      S("chain", "Cause → effect", chain([
        "Weak or stiff ventricle → insufficient cardiac reserve during exercise → exertional symptoms first.",
        "Fluid retention → ↑ filling pressures in the heart.",
        "Left-sided pressure backs into the pulmonary veins and lungs → dyspnea with routine activity, orthopnea, PND, wet cough with frothy sputum, rales.",
        "Lying flat shifts more fluid toward the chest → orthopnea (counted in pillows) and PND waking the patient at night.",
        "Right-sided pressure backs into the systemic veins → ↑ JVP, peripheral edema, ascites, abdominal discomfort.",
        "Stretched, overloaded heart → BNP rises, increasingly as heart failure worsens."
      ]) + Tbl(["Pressure backs up behind…", "Into…", "You see / hear"], [
        ["<strong>Left</strong> ventricle", "Lungs", "Rales, orthopnea, PND, frothy sputum; CXR Kerley lines, pleural effusions"],
        ["<strong>Right</strong> ventricle", "Systemic veins", "↑ JVP, peripheral edema, ascites, anasarca"]
      ]) + HY("Early CM = exertional intolerance (no reserve). Later CM = congestion (fluid backs up behind the failing side).") + clar("lying flat redistributes fluid from the legs back toward the chest, which raises pulmonary congestion — the reason orthopnea and PND are later, fluid-driven symptoms.")),
      S("bedside", "Why it matters clinically", "<p><strong>DCM</strong> follows this order exactly: left-sided HF first (exertional dyspnea, then PND/orthopnea and frothy sputum), then right-sided HF (anasarca, LE edema, abdominal distension).</p><p><strong>RCM</strong> develops <strong>both left and right</strong> HF, and progression is usually rapid. <strong>ARVC</strong> presents with <strong>right-sided</strong> failure (JVD, edema, ascites) because the RV is the diseased chamber.</p><p>From the H&P lecture: JVP reflects right atrial pressure — so a high JVP is right-sided backup made visible. On CXR, Kerley lines and effusions are left-sided backup made visible. BNP helps establish prognosis and severity.</p><p>This is why <strong>diuretics</strong> are a general CM management goal: they reduce the fluid retention that drives congestion.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“Edema and ascites mean left heart failure.”</strong> They are signs of pressure backing up behind the <em>right</em> heart; left-sided backup shows up in the lungs.",
        "<strong>“Early CM symptoms are obviously cardiac.”</strong> Early symptoms are vague exertional ones that are often attributed to aging or deconditioning.",
        "<strong>“A normal CXR rules out cardiomyopathy.”</strong> The CXR is normal in many early cases; echo is the test of choice.",
        "<strong>“Diuretics help every cardiomyopathy.”</strong> They are avoided in HCM with significant LVOT obstruction (see the LVOT concept)."
      ]))
    ], [
      Q("idea", "Why are exertional symptoms usually the first sign of cardiomyopathy?", ["The heart lacks the reserve to increase output when demand rises", "Exercise directly damages the valves", "Resting cardiac output is always zero", "Fluid retention occurs only during exercise"], 0, "Early on, resting output is adequate; insufficient cardiac reserve during exercise produces DOE, fatigue, dizziness, syncope, and chest pain."),
      Q("chain", "Filling pressures in the left heart rise. Where does the pressure back up first?", ["Into the pulmonary veins and lungs", "Into the jugular veins", "Into the hepatic veins", "Into the aorta"], 0, "Behind the left heart lie the lungs, so left-sided pressure backs into the pulmonary circulation → rales, orthopnea, PND, frothy sputum."),
      Q("chain", "A DCM patient's failure progresses from the left to the right side. Which new finding would you predict?", ["Rising JVP, leg edema, and ascites", "Fewer rales and better orthopnea", "A new S4 gallop", "A narrower QRS"], 0, "Right-sided failure backs pressure into the systemic veins → elevated JVP, peripheral edema, ascites, abdominal distension."),
      Q("chain", "Why does a patient with worsening heart failure need more pillows to sleep?", ["Lying flat shifts fluid toward the chest and worsens pulmonary congestion", "Lying flat lowers left atrial pressure", "Pillows increase cardiac contractility", "Orthopnea is caused by right ventricular dilation alone"], 0, "Orthopnea is a fluid-driven symptom of raised left-sided filling pressures; lying flat increases the fluid load on the lungs."),
      Q("bedside", "Heart failure in a cardiomyopathy patient worsens. What would you predict happens to BNP?", ["It rises progressively", "It falls", "It stays normal until death", "It is replaced by troponin as the marker"], 0, "BNP increasingly elevates as heart failure worsens, so it helps establish prognosis and severity."),
      Q("bedside", "An ARVC patient develops heart failure. Which findings fit the chamber involved?", ["JVD, peripheral edema, ascites", "Frothy sputum and rales only", "A harsh murmur that increases with Valsalva", "Apical ballooning on ventriculography"], 0, "ARVC damages the right ventricle, so failure backs up into the systemic veins → right-sided HF signs."),
      Q("traps", "A 50-year-old blames 6 months of breathlessness on stairs on “getting older.” Why should cardiomyopathy still be considered?", ["Early CM symptoms are vague exertional ones often attributed to aging or deconditioning", "Cardiomyopathy never causes exertional symptoms", "Aging always causes heart failure", "Exertional symptoms only occur in valve disease"], 0, "Insufficient reserve causes vague exertional intolerance first, which is easily overlooked as aging or deconditioning."),
      Q("chain", "Which change would reduce the congestion that drives orthopnea and edema in most cardiomyopathies?", ["Reducing fluid retention with a diuretic", "Increasing salt and fluid intake", "Adding a positive inotrope in obstructive HCM", "Stopping the beta-blocker abruptly"], 0, "Congestion comes from fluid retention raising filling pressures; diuretics such as furosemide reduce fluid retention (except in obstructive HCM).")
    ]),

    // ------------------------------------------------------------------
    D("cmp-hcm-stiff-filling", "HCM: a thick ventricle that depends on time and the atrial kick", "In HCM the thick, inelastic LV relaxes poorly, so it fills slowly and leans on atrial contraction at the end of diastole — producing an S4, enlarged atria, and symptoms that worsen when the heart rate rises.", [
      S("idea", "The idea", "<p>HCM comes from mutations in the <strong>sarcomere</strong> (the contractile machinery), inherited <strong>autosomal dominant</strong>. The result is LV hypertrophy — usually <strong>asymmetric</strong>, especially the <strong>septum below the aortic valve</strong>.</p><p>A thick wall is a stiff wall. It loses elasticity and <strong>relaxes poorly</strong>, so blood doesn't flow in easily during early diastole. To finish filling, the ventricle depends on the <strong>atrium squeezing</strong> at the end of diastole. That late atrial push into a stiff ventricle is the <strong>S4</strong>.</p><p>Working harder against a stiff ventricle, the atria themselves become hypertrophied — which shows up on EKG as <strong>abnormal P waves</strong>.</p>"),
      S("chain", "Cause → effect", chain([
        "Sarcomere mutation → asymmetric LV (septal) hypertrophy.",
        "Thick wall + loss of elasticity → impaired relaxation → harder to fill (diastolic dysfunction).",
        "Ventricle relies on atrial contraction to finish filling at end-diastole.",
        "Blood forced into a stiff ventricle → S4 (“ta-lub-dub”), heard just before S1.",
        "Atria work against high resistance → compensatory atrial hypertrophy → abnormal P waves; LVH + abnormal P waves strongly suggests HCM.",
        "Faster heart rate → shorter diastole → even less time to fill → exertional dyspnea, chest pain, presyncope."
      ]) + Tbl(["", "Slower heart rate", "Faster heart rate"], [
        ["Diastolic filling time", "↑ Longer", "↓ Shorter"],
        ["Filling of stiff LV", "↑ Better", "↓ Worse"],
        ["Symptoms", "Improve", "Worsen (exertion)"]
      ]) + HY("HCM = thick, stiff LV that needs time and the atrial kick to fill → S4, atrial enlargement, worse with tachycardia.") + clar("diastole shortens more than systole as heart rate rises, so a stiff ventricle that fills slowly loses the most filling at fast rates. Slowing the rate (the lecture's beta-blocker, which reduces heart rate and myocardial O2 demand) buys filling time.")),
      S("bedside", "Why it matters clinically", "<p><strong>Exam:</strong> S4 at the apex with the bell; cardiac lift/heave from the thick LV. The H&P lecture lists HCM among the LVH states that produce an S4, and notes it may even be palpable.</p><p><strong>EKG:</strong> LVH, abnormal P waves (atrial hypertrophy), deep narrow “dagger-like” Q waves; the apical variant can give giant negative T waves.</p><p><strong>Symptoms</strong> are exertional: DOE, exertional chest pain, exertional syncope, palpitations. <strong>Treatment</strong> of HF symptoms or angina starts with a <strong>beta-blocker</strong> (metoprolol), or a non-dihydropyridine CCB (verapamil, diltiazem) if BB is contraindicated.</p><p><strong>Athlete's heart</strong> also thickens the LV, but it is <strong>symmetric</strong> and usually 13–15 mm; HCM is asymmetric and ≥ 15 mm. Athletic LVH is not a cardiomyopathy.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“S4 means a dilated heart.”</strong> S4 is the stiff or hypertrophic ventricle; S3 is the dilated, volume-overloaded one.",
        "<strong>“HCM is a systolic problem.”</strong> Its defining dysfunction is diastolic; systolic function is usually preserved.",
        "<strong>“Any thick LV in a young athlete is HCM.”</strong> Athletic LVH is symmetric and usually 13–15 mm; HCM is asymmetric and ≥ 15 mm without another cause.",
        "<strong>“Thick LV from hypertension is HCM.”</strong> LVH with a known cause (HTN, aortic stenosis) is a sequela, not a cardiomyopathy."
      ]))
    ], [
      Q("idea", "Why does the HCM ventricle fill poorly?", ["The thick, inelastic wall relaxes poorly in diastole", "The ventricle is dilated and thin", "The mitral valve is stenotic", "The ventricle contracts too weakly to eject"], 0, "Wall thickness and loss of elasticity impair relaxation, making the heart harder to fill — diastolic dysfunction."),
      Q("chain", "Which mechanism produces the S4 in HCM?", ["Atrial contraction forcing blood into a stiff ventricle at end-diastole", "Rapid early filling of a dilated ventricle", "Closure of a stenotic aortic valve", "Turbulent flow across the LVOT in systole"], 0, "S4 comes at the end of diastole, just before S1, when the atrium pushes blood into a stiff or hypertrophic ventricle."),
      Q("chain", "A patient with HCM becomes tachycardic during exercise. What happens to LV filling?", ["It worsens — diastole shortens, leaving less time to fill a stiff ventricle", "It improves — faster rates fill the ventricle better", "It is unchanged because filling is passive", "It improves because the S4 disappears"], 0, "A stiff ventricle needs time to fill; faster rates cut diastolic time, so filling falls and exertional symptoms appear."),
      Q("chain", "Why does HCM often produce abnormal P waves on EKG?", ["The atria hypertrophy as they work to fill a stiff ventricle", "The sinus node is replaced by fat", "The ventricles depolarize before the atria", "Pericardial fluid dampens atrial voltage"], 0, "Compensatory mechanisms cause atrial hypertrophy, giving abnormal P waves; LVH plus abnormal P waves strongly suggests HCM."),
      Q("bedside", "Why does a beta-blocker help the dyspnea and chest pain of HCM?", ["It slows heart rate, lengthening filling time and lowering myocardial O2 demand", "It dilates the LV to hold more blood", "It increases contractility to overcome stiffness", "It removes excess fluid through the kidneys"], 0, "Beta-blockers reduce heart rate and myocardial O2 demand; a slower rate gives the stiff ventricle more time to fill."),
      Q("traps", "A 21-year-old endurance runner has symmetric LV wall thickening of 14 mm. What does this most likely represent?", ["Athlete's heart — physiologic, not a cardiomyopathy", "Hypertrophic cardiomyopathy", "Restrictive cardiomyopathy", "Dilated cardiomyopathy"], 0, "Athletic LVH is symmetric and usually 13–15 mm; HCM is usually asymmetric and ≥ 15 mm without another cause."),
      Q("idea", "What genetic defect drives the hypertrophy in HCM?", ["Autosomal dominant mutations of the cardiac sarcomere", "X-linked dystrophin mutation", "Autosomal dominant desmosomal protein mutation", "Mitochondrial DNA deletion"], 0, "HCM is caused by mutations of the sarcomere or sarcomere-associated proteins, inherited autosomal dominant with incomplete penetrance."),
      Q("traps", "Which gallop would be the WRONG prediction for a classic HCM patient?", ["S3 from a dilated, volume-overloaded ventricle", "S4 from a stiff ventricle", "Palpable presystolic impulse at the apex", "Low-pitched sound just before S1"], 0, "HCM is a stiff-ventricle disease, so it gives an S4 (just before S1, sometimes palpable). S3 is the gallop of dilated cardiomyopathy.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-lvot-dynamic", "Dynamic LVOT obstruction: the smaller the ventricle, the tighter the outlet", "In HCM the thick septum bulges into the outflow tract and the mitral leaflet is pulled toward it in systole, so anything that makes the LV smaller or squeeze harder narrows the outlet and worsens the obstruction.", [
      S("idea", "The idea", "<p>About <strong>2/3 of HCM patients</strong> have <strong>left ventricular outflow tract (LVOT) obstruction</strong>. The thickening sits in the sub-aortic septum — right where blood leaves the LV.</p><p>The lecture's diagram (slide 23) shows <strong>systolic anterior motion (SAM) of the mitral valve</strong>: during systole the mitral leaflet moves toward the thick septum and narrows the exit even more. It also notes that <strong>low resistance and low blood volume worsen the obstruction</strong>.</p><p>The key word is <strong>dynamic</strong>. Unlike a stenotic valve, which is fixed, this outlet changes size beat by beat. A <strong>fuller</strong> ventricle holds the septum and mitral leaflet apart → wider outlet. An <strong>emptier</strong> or harder-squeezing ventricle lets them meet → tighter outlet.</p><p>Picture a doorway with a big piece of furniture beside it. In a crowded, full room the furniture stays put; empty the room and squeeze the walls in, and the furniture blocks the door.</p>"),
      S("chain", "Cause → effect", chain([
        "Asymmetric sub-aortic septal hypertrophy narrows the LV outflow tract.",
        "In systole, the mitral leaflet moves anteriorly toward the septum (SAM) → outlet narrows further.",
        "Smaller LV cavity (less volume) → septum and leaflet closer together → more obstruction.",
        "Lower resistance (vasodilation) → LV empties faster and smaller → more obstruction.",
        "Stronger contraction → cavity squeezes smaller → more obstruction.",
        "More obstruction → higher LVOT gradient → louder murmur, less forward flow → exertional syncope, angina, HF symptoms."
      ]) + Tbl(["Change", "LV size in systole", "LVOT obstruction"], [
        ["↓ Blood volume / preload (dehydration, diuretics, standing)", "Smaller", "<strong>↑ Worse</strong>"],
        ["↓ Resistance / afterload (vasodilators)", "Smaller", "<strong>↑ Worse</strong>"],
        ["↑ Contractility (inotropes, catecholamines)", "Smaller", "<strong>↑ Worse</strong>"],
        ["↑ Volume / resistance; ↓ heart rate and contractility (beta-blocker)", "Larger", "<strong>↓ Better</strong>"]
      ]) + HY("Dynamic LVOT obstruction: empty, unloaded, or hyper-squeezing ventricle = worse; full, slow, gently squeezing ventricle = better.") + clar("the slides give low resistance and low blood volume as worsening factors and list positive inotropes among drugs that worsen obstruction; the common thread is a smaller systolic cavity that brings the septum and mitral leaflet together.")),
      S("bedside", "Why it matters clinically", "<p><strong>Murmur:</strong> a harsh crescendo-decrescendo systolic murmur, best at the <strong>apex and LLSB</strong>. A mitral regurgitation murmur may also occur.</p><p><strong>Severity:</strong> an LVOT gradient <strong>≥ 50 mmHg</strong> is a strong, independent determinant of progressive HF symptoms and stroke death. Echo with Doppler measures it.</p><p><strong>Exercise:</strong> most HCM patients have LVOT obstruction after exercise. Abnormal stress-test findings include failure of BP to rise or exercise-induced hypotension, and arrhythmias at peak or right after exercise.</p><p><strong>Refractory cases:</strong> surgical septal myectomy (cut away the bulge) or alcohol septal ablation (infarct the bulge through a septal perforator off the LAD) physically widen the outlet.</p>" + clar("exercise brings catecholamines (↑ contractility), a faster rate, and vasodilation in working muscle — three of the worsening factors in the table at once, which is why obstruction and exertional syncope cluster around exercise.")),
      S("traps", "Common traps", traps([
        "<strong>“LVOT obstruction is a fixed narrowing like aortic stenosis.”</strong> It is dynamic; it changes with volume, resistance, and contractility. AS is a fixed valve problem.",
        "<strong>“A harder squeeze will push more blood past the obstruction.”</strong> A stronger squeeze shrinks the cavity and tightens the outlet — that is why positive inotropes are avoided.",
        "<strong>“The HCM murmur is loudest at the right upper sternal border like AS.”</strong> The lecture places it at the apex and LLSB; AS is at the RUSB radiating to the carotids.",
        "<strong>“Not every HCM has obstruction, so the drug warnings never matter.”</strong> About 2/3 have LVOT obstruction, and the avoid-list applies to those with significant obstruction."
      ]))
    ], [
      Q("chain", "An HCM patient with LVOT obstruction becomes dehydrated. What happens to the obstruction?", ["It worsens — lower volume makes the LV cavity smaller", "It improves — less volume means less work", "It is unchanged because the obstruction is fixed", "It disappears because preload no longer matters"], 0, "Low blood volume shrinks the cavity, bringing the septum and mitral leaflet together and narrowing the outflow tract."),
      Q("chain", "Systemic vascular resistance falls in an HCM patient with LVOT obstruction. Predict the effect.", ["Obstruction worsens as the LV empties faster and smaller", "Obstruction improves because afterload is lower", "Obstruction is unaffected by resistance", "The murmur becomes diastolic"], 0, "The slides note low resistance worsens obstruction: the LV ejects into less resistance, empties further, and the outlet narrows."),
      Q("idea", "What makes HCM's outflow obstruction “dynamic”?", ["Its severity changes with LV volume, resistance, and contractility", "It is caused by a calcified, fixed aortic valve", "It occurs only during diastole", "It is present only at birth"], 0, "The obstruction is formed by the septum and the systolic anterior motion of the mitral leaflet, so it varies with how full and how forcefully the LV contracts."),
      Q("chain", "Which mitral valve movement adds to the LVOT obstruction in HCM?", ["Systolic anterior motion of the mitral leaflet toward the septum", "Diastolic prolapse into the left atrium", "Fusion of the commissures", "Annular calcification causing stenosis"], 0, "The slide 23 diagram shows systolic anterior motion of the mitral valve narrowing the outflow tract during systole."),
      Q("bedside", "Most HCM patients show LVOT obstruction after exercise. Which mechanism best explains this?", ["Exercise raises contractility and heart rate and lowers resistance, shrinking the LV in systole", "Exercise raises blood volume and slows the heart", "Exercise thins the septum", "Exercise closes the mitral valve permanently"], 0, "Catecholamines, tachycardia, and vasodilation during exercise all make the systolic cavity smaller, tightening the outlet."),
      Q("bedside", "During an HCM stress test, BP fails to rise with exercise. What does this reflect?", ["Outflow obstruction limiting forward flow as demand rises — an abnormal, high-risk finding", "A normal, expected response in HCM", "A falsely low cuff reading only", "Improvement of diastolic filling"], 0, "Failure of BP to increase or exercise-induced hypotension is an abnormal finding; hypotension on stress testing is also a sudden-death risk factor."),
      Q("bedside", "Why does surgical septal myectomy relieve HCM heart failure symptoms?", ["It removes part of the septum, widening the outflow tract", "It replaces the aortic valve", "It increases contractility", "It dilates the left ventricle"], 0, "Myectomy (or alcohol septal ablation) removes or infarcts the hypertrophied septum to enlarge the outflow tract."),
      Q("traps", "A student says “squeeze harder and you'll push blood past an HCM obstruction.” Why is that wrong?", ["A stronger squeeze shrinks the cavity and narrows the outlet further", "Contractility has no effect on the outflow tract", "The obstruction is in the mitral valve, not the outflow tract", "HCM ventricles cannot change contractility"], 0, "Higher contractility empties the LV further, bringing the septum and mitral leaflet together; this is why positive inotropes worsen obstruction."),
      Q("bedside", "An HCM patient's LVOT gradient is 60 mmHg. What does this predict?", ["Higher risk of progressive heart failure symptoms and stroke death", "No clinical significance", "Spontaneous resolution", "Systolic failure with EF ≤ 40%"], 0, "LVOT obstruction ≥ 50 mmHg is a strong, independent determinant of progressive HF symptoms and stroke death.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-hcm-maneuvers", "Why the HCM murmur gets louder on standing and softer on squatting", "Because LVOT obstruction depends on LV size, maneuvers that shrink the ventricle (Valsalva, standing from a squat) make the HCM murmur louder, and those that fill it (squatting) make it softer — the opposite of aortic stenosis.", [
      S("idea", "The idea", "<p>Most murmurs get <strong>louder</strong> when more blood flows through them. HCM is the famous exception, because its obstruction is <strong>dynamic</strong>: less blood in the LV means a tighter outlet, more turbulence, and a louder murmur.</p><p>The lecture's augmentation for HCM is to auscultate during a <strong>Valsalva strain</strong> or as the patient <strong>stands from squatting</strong>. Both of these drop venous return (preload).</p><p>Compare <strong>aortic stenosis</strong> from the valvular lecture: a fixed valve narrowing that is <strong>loudest with squatting and softer with Valsalva</strong>. More blood through a fixed hole = more noise. Same maneuvers, opposite direction — that contrast is the whole point.</p>" + clar("Valsalva (straining against a closed glottis) raises chest pressure and reduces venous return; standing pools blood in the legs and reduces venous return; squatting returns blood to the heart and raises venous return and resistance. Changing preload changes LV size, which in HCM changes the outlet.")),
      S("chain", "Cause → effect", chain([
        "Patient strains (Valsalva) or stands from a squat.",
        "Venous return falls → less preload → smaller LV cavity.",
        "Septum and mitral leaflet move closer → LVOT narrows.",
        "Greater gradient and turbulence → HCM murmur louder.",
        "Squatting reverses it: ↑ venous return (and resistance) → larger LV → wider outlet → murmur softer."
      ]) + Tbl(["Maneuver", "Venous return / LV size", "HCM (dynamic LVOT)", "Aortic stenosis (fixed)"], [
        ["Valsalva strain", "↓", "<strong>Louder</strong>", "Softer"],
        ["Squat → stand", "↓", "<strong>Louder</strong>", "Softer"],
        ["Squatting", "↑", "<strong>Softer</strong>", "Louder"]
      ]) + HY("HCM murmur: ↓ preload → louder; ↑ preload → softer. AS does the opposite.") + Mn("Shrink it, hear it", "Anything that shrinks the LV (strain, stand) makes the HCM murmur louder.")),
      S("bedside", "Why it matters clinically", "<p>A young patient with a <strong>harsh crescendo-decrescendo systolic murmur at the apex/LLSB</strong> that <strong>gets louder when he stands up from a squat</strong> is the classic HCM vignette. The direction of change separates it from AS, which shares the crescendo-decrescendo shape.</p><p>The same physiology explains real-life symptoms: standing up quickly, straining, or being volume-depleted all shrink the LV and can provoke presyncope in obstructive HCM.</p><p>Mitral valve prolapse (valvular lecture) is another preload-sensitive finding: standing/Valsalva moves the click earlier, squatting moves it later — but MVP is a mid-systolic click, not a harsh outflow murmur.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“Valsalva makes every murmur louder.”</strong> Valsalva lowers venous return, which softens most murmurs (including AS); HCM is the exception.",
        "<strong>“Squatting makes the HCM murmur louder.”</strong> Squatting fills the LV and widens the outlet, softening the HCM murmur. It is AS that gets louder with squatting.",
        "<strong>“Same shape = same lesion.”</strong> HCM and AS are both crescendo-decrescendo systolic murmurs; location (apex/LLSB vs RUSB → carotids) and maneuver response tell them apart."
      ]))
    ], [
      Q("chain", "An HCM patient performs a Valsalva strain. What happens to the murmur?", ["It gets louder — less preload shrinks the LV and tightens the outlet", "It gets softer — less blood flows through the outflow tract", "It is unchanged", "It becomes a diastolic rumble"], 0, "Valsalva lowers venous return; the smaller LV brings the septum and mitral leaflet together, increasing obstruction and the murmur."),
      Q("chain", "An HCM patient moves from standing to squatting. Predict the murmur.", ["Softer — more venous return enlarges the LV and widens the outlet", "Louder — squatting increases turbulence", "Unchanged — squatting affects only right-sided murmurs", "It disappears and is replaced by an S3"], 0, "Squatting raises venous return and LV size, which widens the dynamic outflow tract and softens the HCM murmur."),
      Q("chain", "A patient with aortic stenosis squats. Predict the murmur.", ["Louder — more flow through a fixed narrowing", "Softer — like HCM", "Unchanged", "It becomes holosystolic"], 0, "AS is a fixed obstruction: more blood through it makes more turbulence. The valvular lecture states AS is loudest with squatting, softer with Valsalva."),
      Q("bedside", "A harsh crescendo-decrescendo systolic murmur at the LLSB gets louder when the patient stands up from squatting. Which mechanism explains this?", ["Reduced preload worsening a dynamic LVOT obstruction", "Increased preload through a stenotic aortic valve", "Increased flow through a regurgitant mitral valve", "Rapid early filling of a dilated ventricle"], 0, "Squat-to-stand drops venous return; in HCM the smaller LV narrows the outflow tract and the murmur intensifies."),
      Q("idea", "Why does the HCM murmur respond to maneuvers in the opposite direction from most murmurs?", ["Its obstruction is dynamic and tightens when the LV is smaller", "It is produced in diastole", "It is caused by the right ventricle", "It is a fixed valve narrowing"], 0, "Most murmurs track flow volume; the HCM obstruction itself shrinks as the LV empties, so less volume means more obstruction."),
      Q("traps", "Which two maneuvers does the lecture use to augment auscultation in suspected HCM?", ["Valsalva strain and standing from squatting", "Squatting and leaning forward", "Left lateral decubitus and inspiration", "Handgrip and sitting up"], 0, "Both Valsalva and squat-to-stand reduce preload, which accentuates the dynamic LVOT murmur."),
      Q("traps", "A crescendo-decrescendo murmur is softer with Valsalva and louder with squatting, heard at the RUSB radiating to the carotids. Which lesion fits better?", ["Aortic stenosis", "Hypertrophic cardiomyopathy with LVOT obstruction", "Mitral valve prolapse", "Dilated cardiomyopathy"], 0, "That is the fixed-obstruction pattern and location of AS; HCM gets louder with Valsalva and is heard at the apex/LLSB.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-hcm-drug-logic", "Which drugs help and which hurt obstructive HCM", "In HCM with LVOT obstruction, drugs that slow and soften the heartbeat (beta-blockers, non-dihydropyridine CCBs) help, while drugs that shrink or unload the ventricle or make it squeeze harder (inotropes, vasodilators, diuretics) worsen the obstruction.", [
      S("idea", "The idea", "<p>Use the dynamic-outlet rule from the previous concept: anything that makes the LV <strong>smaller</strong> or squeeze <strong>harder</strong> tightens the outlet. Now sort the drugs:</p><ul><li><strong>Positive inotropes</strong> (dopamine, dobutamine, digoxin) → harder squeeze → worse.</li><li><strong>Vasodilators</strong> (dihydropyridine CCBs like nifedipine/amlodipine, ACEi/ARBs like lisinopril/losartan, nitrates like nitroglycerin) → lower resistance → LV empties smaller → worse.</li><li><strong>Diuretics</strong> (furosemide) → less blood volume → smaller LV → worse.</li></ul><p>The helpers do the opposite: <strong>beta-blockers</strong> (metoprolol) slow the heart and reduce its squeeze; <strong>non-dihydropyridine CCBs</strong> (verapamil, diltiazem) are used when a BB is contraindicated (e.g. asthma) or not tolerated.</p><p>The striking part: many of the drugs that <em>treat</em> a dilated heart are the ones that <em>harm</em> an obstructed one.</p>"),
      S("chain", "Cause → effect", chain([
        "Drug ↑ contractility, ↓ resistance, or ↓ volume → smaller LV cavity in systole.",
        "Smaller cavity → septum and mitral leaflet closer → LVOT obstruction ↑.",
        "↑ Obstruction → worse HF symptoms and angina.",
        "Beta-blocker or non-DHP CCB → ↓ heart rate and contractility → longer filling, larger cavity → obstruction ↓.",
        "Refractory symptoms → mechanical fix (septal myectomy or alcohol septal ablation)."
      ]) + Tbl(["Drug class", "Example", "Effect on LVOT obstruction", "Same drug in DCM"], [
        ["Beta-blocker", "Metoprolol", "<strong>↓ First line</strong>", "Used (↓ HR, ↓ O2 demand)"],
        ["Non-DHP CCB", "Verapamil, diltiazem", "<strong>↓</strong> (if BB contraindicated)", "—"],
        ["Positive inotrope", "Dopamine, dobutamine, digoxin", "<strong>↑ Avoid</strong>", "Digoxin used"],
        ["DHP CCB", "Nifedipine, amlodipine", "<strong>↑ Avoid</strong>", "—"],
        ["ACEi / ARB", "Lisinopril, losartan", "<strong>↑ Avoid</strong>", "ACEi used (afterload ↓)"],
        ["Nitrate", "Nitroglycerin", "<strong>↑ Avoid</strong>", "Used (preload & afterload ↓)"],
        ["Diuretic", "Furosemide", "<strong>↑ Avoid</strong>", "Used (fluid ↓)"]
      ]) + HY("Obstructive HCM: slow it down (BB, verapamil/diltiazem); don't squeeze it, dilate it, or dry it out.") + Mn("Avoid “I.V.D.” in obstructive HCM", "Inotropes, Vasodilators, Diuretics.") + clar("beta-blockers and non-DHP CCBs lower heart rate and contractility; slower, gentler beats keep the LV larger in systole and lengthen diastolic filling, which is why they relieve obstruction-related HF symptoms and angina.")),
      S("bedside", "Why it matters clinically", "<p>This is one of the lecture's highest-yield applications: choose the initial drug for HCM HF symptoms (<strong>beta-blocker</strong>), switch to a <strong>non-DHP CCB</strong> for an asthmatic or BB-intolerant patient (combination possible but more bradyarrhythmia), and recognize the <strong>avoid list</strong>.</p><p>It also explains a classic danger: a patient with exertional chest pain from HCM given <strong>nitroglycerin</strong> as if it were angina from CAD may get worse, because the vasodilation lowers preload and resistance and tightens the outlet.</p><p>Note the contrast with general CM management, which lists diuretics to reduce fluid retention, and with DCM, which uses ACEi, nitroglycerin, diuretics, and digoxin.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“All CCBs are fine in HCM.”</strong> Non-dihydropyridines (verapamil, diltiazem) slow the heart and help; dihydropyridines (nifedipine, amlodipine) are vasodilators and worsen obstruction.",
        "<strong>“Chest pain → give nitroglycerin.”</strong> In obstructive HCM nitrates are on the avoid list.",
        "<strong>“Heart failure → give a diuretic.”</strong> Diuretics shrink the LV and worsen obstruction in significant LVOT obstruction.",
        "<strong>“Digoxin is for weak hearts, so it's harmless here.”</strong> Digoxin is a positive inotrope — useful in DCM, avoided in obstructive HCM."
      ]))
    ], [
      Q("chain", "An HCM patient with significant LVOT obstruction is started on nitroglycerin. Predict the effect.", ["Obstruction and symptoms worsen — vasodilation shrinks the LV", "Obstruction improves — lower afterload helps every heart", "No effect on the outflow tract", "The S4 disappears and filling improves"], 0, "Nitrates reduce preload and afterload, so the LV empties smaller and the outlet tightens; the lecture lists nitrates to avoid."),
      Q("chain", "Why is dobutamine avoided in obstructive HCM?", ["It increases contractility, shrinking the systolic cavity and tightening the outlet", "It slows the heart excessively", "It causes fluid retention", "It thickens the septum within hours"], 0, "Positive inotropes squeeze the LV smaller, bringing the septum and mitral leaflet together and worsening obstruction."),
      Q("idea", "What is the first-line drug for heart failure symptoms or angina due to LVOT obstruction?", ["A beta-blocker such as metoprolol", "A dihydropyridine CCB such as amlodipine", "An ACE inhibitor such as lisinopril", "A loop diuretic such as furosemide"], 0, "Beta-blockers are initial therapy; they slow the rate and reduce contractility, easing the dynamic obstruction."),
      Q("bedside", "An asthmatic patient with obstructive HCM needs symptom control. Which drug follows the same mechanism as a beta-blocker without the bronchospasm risk?", ["Verapamil (non-dihydropyridine CCB)", "Nifedipine (dihydropyridine CCB)", "Losartan (ARB)", "Digoxin (inotrope)"], 0, "Non-DHP CCBs (verapamil, diltiazem) slow the heart and are used when a beta-blocker is contraindicated, such as in asthma."),
      Q("chain", "Why do dihydropyridine CCBs worsen HCM obstruction while verapamil helps?", ["Dihydropyridines mainly vasodilate (↓ resistance); verapamil mainly slows the heart", "Dihydropyridines slow the heart; verapamil vasodilates", "Both increase contractility", "Dihydropyridines are diuretics"], 0, "Nifedipine/amlodipine are vasodilators on the avoid list; non-DHPs like verapamil reduce rate and contractility."),
      Q("chain", "A patient with obstructive HCM is given furosemide for mild ankle swelling. What would you predict?", ["Worse obstruction — lower blood volume shrinks the LV", "Better obstruction — less fluid reduces wall stress", "No change in the outflow tract", "Reversal of the septal hypertrophy"], 0, "Diuretics lower blood volume; low volume worsens the dynamic LVOT obstruction, so they are avoided in significant obstruction."),
      Q("traps", "Digoxin is used in dilated cardiomyopathy. Why is it avoided in HCM with LVOT obstruction?", ["It is a positive inotrope, which worsens dynamic obstruction", "It causes vasodilation", "It is a diuretic", "It is contraindicated in all cardiomyopathies"], 0, "The weak DCM ventricle benefits from inotropy; the obstructed HCM ventricle is harmed by a harder squeeze."),
      Q("bedside", "HCM symptoms persist despite a beta-blocker and verapamil. What is the next step that addresses the mechanism directly?", ["Septal myectomy or alcohol septal ablation to widen the outflow tract", "Add amlodipine to lower afterload", "Add dobutamine to increase output", "Add high-dose furosemide"], 0, "Refractory obstruction is treated mechanically: removing or infarcting the hypertrophied septum widens the LVOT.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-dilated-remodeling", "The dilated ventricle: stretched, weak, and leaky", "When the LV dilates and weakens, it ejects too little, fills with leftover volume (S3), stretches its valve rings (mitral and tricuspid regurgitation), and shifts the PMI outward — so treatment unloads it and helps it squeeze.", [
      S("idea", "The idea", "<p>DCM is the <strong>most common</strong> cardiomyopathy. Causes are mixed: genetic (~35%, e.g. dystrophin mutations in muscular dystrophy), alcohol, pregnancy (PPCM), drugs/toxins (doxorubicin, hydroxychloroquine), and idiopathic (~50%).</p><p>Whatever the cause, the picture is the same: a <strong>big, weak</strong> ventricle. Each beat ejects only a small fraction (EF ≤ 40%), so blood is left behind. The next wave of filling crashes into an already full, over-distended chamber — that's the <strong>S3</strong>.</p><p>As the ventricle stretches, it also pulls on its valves, so <strong>mitral and tricuspid regurgitation</strong> murmurs appear. The enlarged heart shows up as <strong>cardiomegaly</strong> on CXR and a <strong>displaced PMI</strong> on exam.</p>" + clar("dilation stretches the ring the AV valve leaflets attach to, so the leaflets no longer meet and leak in systole; the slides list mitral and tricuspid regurgitation murmurs in DCM.")),
      S("chain", "Cause → effect", chain([
        "Myocyte injury (genetic, alcohol, toxin, pregnancy, idiopathic) → weak contraction.",
        "Reduced inward systolic motion → EF ≤ 40% → blood left in the ventricle.",
        "Ventricle dilates (normal or thin walls) → cardiomegaly, displaced PMI.",
        "Rapid early filling of an over-distended ventricle → S3 (“lub-dub-ta”), louder with tachycardia.",
        "Stretched AV valve rings → mitral and tricuspid regurgitation murmurs.",
        "Forward output falls and pressure backs up → left HF, then right HF."
      ]) + Tbl(["Treatment", "Mechanism in DCM"], [
        ["Beta-blocker", "↓ Heart rate and myocardial O2 demand"],
        ["ACE inhibitor", "↓ Afterload — easier for a weak LV to eject"],
        ["Nitroglycerin", "↓ Preload and afterload"],
        ["Diuretic (furosemide)", "↓ Fluid retention and congestion"],
        ["Digoxin", "Positive inotrope — helps a weak ventricle squeeze"],
        ["Anticoagulant", "Prevent thromboembolism"],
        ["Remove the cause (e.g. stop ETOH)", "Early alcoholic DCM may reverse"]
      ]) + HY("DCM: weak, dilated ventricle → S3, MR/TR, displaced PMI. Treat by unloading (ACEi, nitrates, diuretics) and supporting the squeeze (digoxin).")),
      S("bedside", "Why it matters clinically", "<p><strong>Exam:</strong> S3 at the apex in the left lateral position, tricuspid/mitral regurgitation murmurs, rales, elevated JVP, peripheral edema, ascites. The H&P lecture adds that maneuvers increasing venous return accentuate S3.</p><p><strong>Workup:</strong> echo shows LV cavity dilation, normal or ↓ wall thickness, reduced inward systolic motion, EF ≤ 40%; CXR shows cardiomegaly and Kerley lines ± effusions; EKG most often sinus tach and LBBB, then atrial fibrillation; BNP tracks severity.</p><p><strong>PPCM</strong> behaves like DCM and is treated similarly, but <strong>ACEi/ARBs are avoided in pregnancy and breastfeeding</strong>.</p><p>DCM is the <strong>most common reason for cardiac transplantation</strong>.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“A dilated ventricle has thick walls.”</strong> DCM walls are normal or decreased in thickness; thick walls point to HCM.",
        "<strong>“The regurgitant murmurs mean primary valve disease.”</strong> In DCM, MR and TR follow the ventricle's dilation.",
        "<strong>“S3 is always pathologic.”</strong> The H&P lecture notes S3 also occurs in hyperdynamic states; in DCM it reflects an over-distended, failing ventricle.",
        "<strong>“HCM drugs and DCM drugs are interchangeable.”</strong> ACEi, nitrates, diuretics, and digoxin help DCM but are on HCM's avoid list when LVOT obstruction is significant."
      ]))
    ], [
      Q("chain", "A DCM ventricle ejects only 30% of its volume each beat. What happens to the blood left behind?", ["It stays in the ventricle, which dilates and becomes over-distended", "It flows backward into the aorta", "It is absorbed by the myocardium", "It is ejected later in diastole"], 0, "Low EF leaves residual volume; the chamber dilates, and the next filling wave into the over-distended ventricle produces an S3."),
      Q("chain", "Why do mitral and tricuspid regurgitation murmurs appear in DCM?", ["Dilation stretches the valve rings so the leaflets no longer seal", "The valves calcify and narrow", "The septum pulls the mitral leaflet into the outflow tract", "The atria contract against closed valves"], 0, "As the ventricle enlarges, the AV valve rings stretch and the leaflets leak — functional regurgitation."),
      Q("idea", "Which gallop is characteristic of dilated cardiomyopathy?", ["S3 — early diastolic filling of an over-distended ventricle", "S4 — atrial kick into a stiff ventricle", "Opening snap of the mitral valve", "Ejection click of the aortic valve"], 0, "S3 (“Kentucky”) occurs just after S2 during rapid filling and is the gallop of the dilated heart."),
      Q("chain", "A DCM patient becomes more tachycardic. Predict the S3.", ["More prominent — the lecture notes S3 is accentuated in tachycardic patients", "It disappears", "It turns into an S4", "It moves into systole"], 0, "The slides state S3 is accentuated in more tachycardic patients."),
      Q("bedside", "Why does an ACE inhibitor help a dilated ventricle?", ["It lowers afterload, so a weak ventricle can eject more easily", "It increases contractility", "It thickens the ventricular wall", "It slows the heart rate"], 0, "The lecture lists ACE inhibitors for afterload reduction in DCM; less resistance means a weak LV can eject more."),
      Q("bedside", "Where would you predict the PMI in advanced DCM?", ["Displaced laterally/downward because the ventricle is enlarged", "In its normal location because the walls are thin", "At the right sternal border", "Not palpable because the heart is small"], 0, "The dilated, enlarged heart displaces the PMI; cardiomegaly is seen on CXR."),
      Q("traps", "Echo shows a dilated LV with walls of 7 mm and EF 30%. A student calls it HCM because the heart is “big.” What's wrong?", ["HCM has thick (≥ 15 mm) walls and preserved EF; thin walls with low EF are DCM", "HCM always has EF below 20%", "DCM is diagnosed only by biopsy", "Wall thickness doesn't matter on echo"], 0, "DCM: dilated cavity, normal or ↓ wall thickness, EF ≤ 40%. HCM: thick walls, usually preserved systolic function."),
      Q("bedside", "A heavy drinker with early DCM stops drinking. What outcome does the lecture suggest is possible?", ["Partial reversal of the cardiomyopathy", "Guaranteed progression regardless", "Conversion to HCM", "Immediate need for transplant"], 0, "Alcoholic DCM may be reversible in early stages if the patient abstains; correcting reversible causes is the first treatment step.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-stasis-and-scar", "Why sick myocardium clots and short-circuits", "A poorly contracting or enlarged chamber lets blood sit still and clot (thromboembolism), and diseased, scarred muscle conducts unevenly, creating tachyarrhythmias — sustained VT that degrades to VF is the usual cause of sudden death.", [
      S("idea", "The idea", "<p>The slides make two promises about almost every cardiomyopathy: <strong>increased thromboembolism risk</strong> and <strong>atrial and ventricular tachyarrhythmias</strong>.</p><p><strong>Clots:</strong> blood that keeps moving stays liquid. A weak, dilated ventricle, or atria that quiver in atrial fibrillation instead of squeezing, leave pools of slow blood — and slow blood clots. A clot can break off and travel (stroke, PE).</p><p><strong>Arrhythmias:</strong> normal myocardium conducts an impulse like a smooth sheet. Thick, stretched, inflamed, or scarred muscle (fibrosis, fat) conducts unevenly, so impulses can loop and fire too fast. In the ventricles that means <strong>sustained VT → VF → asystole</strong>: sudden cardiac death.</p>" + clar("blood stasis is one of the classic drivers of clot formation; the atrial fibrillation link is why anticoagulation follows AF in HCM.")),
      S("chain", "Cause → effect", chain([
        "Weak contraction (DCM) or quivering atria (AF, common in CM) → slow-moving blood in a chamber.",
        "Stasis → thrombus (e.g. mural thrombus seen on echo).",
        "Thrombus breaks free → thromboembolism (stroke, PE).",
        "Hypertrophy, stretch, inflammation, or fibro-fatty scar → uneven electrical conduction.",
        "Atrial and ventricular tachyarrhythmias → sustained VT → VF → asystole = sudden cardiac death."
      ]) + Tbl(["Problem", "Mechanism", "Countermeasure"], [
        ["Thromboembolism", "Stasis in a weak chamber or fibrillating atria", "Anticoagulant (warfarin or DOAC)"],
        ["Fast rates", "Abnormal myocardium", "Beta-blocker (rate control)"],
        ["Rhythm disturbances", "Damaged conduction", "Implantable pacemaker (rhythm control)"],
        ["Sustained VT/VF", "Scarred/abnormal ventricle", "<strong>ICD</strong> — terminates the rhythm with a shock"]
      ]) + HY("Stasis → clot → anticoagulate. Scar → VT/VF → ICD (the only effective prevention of sudden cardiac death in HCM).")),
      S("bedside", "Why it matters clinically", "<p><strong>HCM:</strong> atrial fibrillation → oral anticoagulation (warfarin or DOAC). Ventricular arrhythmias or high SCD risk → <strong>ICD</strong>, the only effective prevention strategy against sudden cardiac death. HCM is the leading cause of SCD in young athletes; risk is greatest in patients < 40, with prior non-sustained VT, massive hypertrophy, hypotension on stress test, or family history of SCA.</p><p><strong>DCM:</strong> anticoagulants to prevent thromboembolism; EKG often shows atrial fibrillation (2nd most common finding).</p><p><strong>Myocarditis:</strong> anticoagulation if an embolic event (e.g. PE) or <strong>mural thrombi on echo</strong>; can present with ventricular arrhythmias or complete heart block.</p><p><strong>During arrest:</strong> prompt defibrillation and CPR.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“Sudden death in CM is from asystole.”</strong> Asystole is the end; the usual cause is sustained VT that degrades into VF.",
        "<strong>“Anti-arrhythmic drugs prevent sudden death in HCM.”</strong> The lecture names the ICD as the only effective prevention strategy.",
        "<strong>“Only dilated hearts form clots.”</strong> Atrial fibrillation in HCM also raises thromboembolism risk, and myocarditis can produce mural thrombi.",
        "<strong>“A pacemaker and an ICD do the same thing.”</strong> Pacemakers provide rhythm control; ICDs add rhythm control plus a shock for VT/VF."
      ]))
    ], [
      Q("chain", "A DCM ventricle contracts weakly. Why does that raise the risk of stroke?", ["Slow-moving blood in the chamber forms a thrombus that can embolize", "Weak contraction raises blood pressure in the brain", "The ventricle releases fat emboli", "Low EF directly ruptures cerebral vessels"], 0, "Stasis in a poorly contracting chamber allows thrombus to form; an embolus can travel to the brain."),
      Q("chain", "An HCM patient develops atrial fibrillation. Which complication does this raise, and what is the response?", ["Thromboembolism — start oral anticoagulation (warfarin or DOAC)", "Hypertension — start a diuretic", "Pericarditis — start NSAIDs", "Valve stenosis — schedule replacement"], 0, "Fibrillating atria don't squeeze, so blood stagnates and clots; the lecture treats AF in HCM with warfarin or a DOAC."),
      Q("idea", "What rhythm sequence usually causes sudden death in cardiomyopathy?", ["Sustained ventricular tachycardia → ventricular fibrillation → asystole", "Sinus bradycardia → first-degree block", "Atrial flutter → sinus rhythm", "Premature atrial contractions → sinus tachycardia"], 0, "Sudden death is typically due to sustained VT progressing to VF and then asystole."),
      Q("bedside", "Which intervention is the only effective prevention strategy against sudden cardiac death in HCM?", ["Implantable cardioverter-defibrillator", "Beta-blocker alone", "Daily aspirin", "Septal myectomy"], 0, "An ICD detects VT/VF and shocks it; the lecture calls it the only effective SCD prevention in HCM."),
      Q("bedside", "Echo in a myocarditis patient shows a mural thrombus. What does the lecture direct?", ["Anticoagulation", "Positive inotropes only", "Immediate septal ablation", "No treatment — thrombi resolve spontaneously"], 0, "Anticoagulation is necessary in myocarditis if an embolic event or mural thrombi are detected on echo."),
      Q("chain", "Why does fibrosis or fatty replacement of myocardium promote ventricular arrhythmias?", ["It makes electrical conduction uneven, allowing abnormal fast rhythms", "It speeds conduction uniformly", "It eliminates all electrical activity", "It slows the heart into bradycardia only"], 0, "Abnormal tissue conducts unevenly (the lecture's epsilon-wave example), setting up tachyarrhythmias like VT."),
      Q("bedside", "Which HCM patient has the greatest predicted risk of sudden cardiac arrest?", ["A 25-year-old with non-sustained VT, massive hypertrophy, and hypotension on stress test", "A 70-year-old with mild hypertrophy and no arrhythmias", "A 45-year-old with an S4 only", "A 60-year-old with controlled symptoms on metoprolol and no family history"], 0, "Risk is greatest in patients < 40 with prior non-sustained VT, massive hypertrophy, hypotension on stress test, and family history of SCA."),
      Q("traps", "A student says asystole is the arrhythmia that causes sudden death in cardiomyopathy. What's the correction?", ["Asystole is the end stage; sustained VT degrading to VF is the usual cause", "Atrial fibrillation alone is the usual cause", "Sinus tachycardia is the usual cause", "Complete heart block is always the cause"], 0, "The lecture's sequence is VT → VF → asystole; the initiating arrhythmia is ventricular.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-restrictive-filling", "Restrictive physiology: a rigid box that fills under pressure", "In RCM the ventricles are normal-sized and usually normal-thickness but rigid, so they accept blood only at high pressure — the atria dilate, both sides back up, and heart failure progresses quickly even though the squeeze is preserved.", [
      S("idea", "The idea", "<p>Imagine trying to pour water into a rigid plastic box instead of a balloon. The box won't stretch, so as you pour, pressure climbs fast and the water backs up into the funnel.</p><p>That is <strong>restrictive cardiomyopathy</strong>. The ventricles are <strong>not dilated</strong> and usually <strong>not thickened</strong> (infiltrative disease can thicken them), but their walls are <strong>rigid</strong>. Filling is restricted, filling pressures are high, and the chambers upstream — the <strong>atria</strong> — dilate. <strong>LV systolic function usually stays normal</strong> until the disease is severe.</p><p>Etiologies include radiation therapy, amyloidosis, sarcoidosis, and idiopathic (~50%).</p>"),
      S("chain", "Cause → effect", chain([
        "Infiltration or fibrosis (amyloid, sarcoid, radiation, idiopathic) → rigid ventricular walls.",
        "Ventricles can't expand → restrictive filling → elevated filling pressures.",
        "Pressure backs into both atria → bi-atrial enlargement (cardiomegaly on CXR from the atria).",
        "Left-sided backup → SOB, orthopnea, PND, pulmonary congestion.",
        "Right-sided backup → JVD, peripheral edema, ascites.",
        "Systolic squeeze preserved early → but filling limit means output can't rise → rapid HF progression and poor survival."
      ]) + Tbl(["", "RCM", "HCM", "DCM"], [
        ["Ventricle size", "Not dilated", "Not dilated", "<strong>Dilated</strong>"],
        ["Wall thickness", "Usually normal (rigid)", "<strong>Asymmetric ↑</strong>", "Normal or ↓"],
        ["Atria", "<strong>Bi-atrial enlargement</strong>", "May hypertrophy", "May enlarge"],
        ["Systolic function", "Preserved until severe", "Usually preserved", "<strong>↓ EF ≤ 40%</strong>"],
        ["Main defect", "Severe diastolic, restrictive filling", "Diastolic ± LVOT obstruction", "Systolic"]
      ]) + HY("RCM = normal-size, stiff ventricles + big atria + preserved EF. Filling, not squeezing, fails.")),
      S("bedside", "Why it matters clinically", "<p><strong>Presentation:</strong> left AND right HF, usually progressing rapidly — SOB, orthopnea, PND, JVD, peripheral edema, ascites, a gallop (S3 or S4), and regurgitant murmurs.</p><p><strong>Workup:</strong> EKG nonspecific, may show <strong>decreased QRS amplitude</strong>; CXR may show cardiomegaly (from the atria) and pulmonary congestion; echo (test of choice) shows non-dilated, non-hypertrophied ventricles, bi-atrial enlargement, preserved systolic LV, abnormal diastolic function. <strong>Cardiac MRI</strong> shows infiltration/fibrosis patterns that identify the specific form; <strong>endomyocardial biopsy</strong> is most accurate if MRI is equivocal.</p><p><strong>Prognosis:</strong> lowest one-year survival of DCM, HCM, and RCM; management targets HF and arrhythmia, and transplant is seldom advised because of the underlying primary disease.</p>" + clar("when abnormal material infiltrates the myocardium, the EKG can show lower voltage even if the wall looks thick, because the added tissue is not electrically active muscle — consistent with the slide's “decreased QRS amplitude.”")),
      S("traps", "Common traps", traps([
        "<strong>“Cardiomegaly on CXR means the ventricles are dilated.”</strong> In RCM the enlarged silhouette comes from the atria.",
        "<strong>“Preserved EF means a mild disease.”</strong> RCM has preserved systolic function yet the worst one-year survival of the three.",
        "<strong>“Stiff ventricle = HCM.”</strong> HCM is stiff because it is thick; RCM is stiff with usually normal thickness.",
        "<strong>“Echo identifies the cause of RCM.”</strong> Echo shows the restrictive pattern; cardiac MRI or biopsy identifies infiltration and the specific form."
      ]))
    ], [
      Q("idea", "What is the core mechanical defect in restrictive cardiomyopathy?", ["Rigid ventricles that fill only at high pressure", "Thin, dilated ventricles that can't squeeze", "Dynamic obstruction of the outflow tract", "Fibro-fatty replacement of the right ventricle"], 0, "RCM's ventricular walls are rigid, giving severe diastolic dysfunction and restrictive filling with elevated filling pressures."),
      Q("chain", "Filling pressures rise behind rigid ventricles. Which chambers enlarge?", ["Both atria", "Both ventricles", "Only the right ventricle", "None — no chamber changes size"], 0, "High ventricular filling pressures back into the atria, producing bi-atrial enlargement while the ventricles stay non-dilated."),
      Q("chain", "Both ventricles in RCM are stiff. Which pattern of heart failure would you predict?", ["Both left- and right-sided failure, progressing rapidly", "Left-sided only, progressing slowly", "Right-sided only, from RV dilation", "No heart failure because EF is preserved"], 0, "RCM develops left and right heart failure, and progression is usually rapid."),
      Q("chain", "An RCM patient's ventricle cannot stretch to accept more blood during exercise. What happens to output?", ["It cannot rise much, because filling is the limiting step", "It rises normally because systolic function is preserved", "It rises above normal from the high filling pressures", "It falls to zero"], 0, "A preserved squeeze can't help if the ventricle can't fill; limited filling caps the output."),
      Q("bedside", "An RCM pattern is seen on echo. Which test next identifies infiltration or fibrosis and points to the specific cause?", ["Cardiac MRI", "Exercise stress test", "Troponin", "Holter monitor"], 0, "Cardiac MRI shows the presence or absence of infiltration and fibrosis patterns that inform the specific form; biopsy if MRI is equivocal."),
      Q("traps", "A patient has preserved EF and normal wall thickness. Why might RCM still be the worst prognosis of the three main types?", ["Severe restrictive filling causes rapidly progressive biventricular failure", "Preserved EF always means a benign course", "RCM always resolves within weeks", "RCM never causes heart failure"], 0, "RCM has the lowest one-year survival compared with DCM and HCM; most patients die within a few years of diagnosis."),
      Q("bedside", "Which EKG finding may accompany restrictive cardiomyopathy?", ["Decreased QRS amplitude", "Deep dagger-like Q waves and giant negative T waves", "Epsilon waves in V1", "ST elevation with clean coronaries"], 0, "The lecture lists nonspecific EKG abnormalities in RCM, which may include decreased QRS amplitude."),
      Q("traps", "Which pair best distinguishes RCM from HCM on echo?", ["RCM: normal wall thickness with bi-atrial enlargement; HCM: asymmetric wall ≥ 15 mm", "RCM: dilated LV; HCM: thin walls", "RCM: low EF; HCM: low EF", "RCM: RV fat; HCM: LV fat"], 0, "Both are diastolic diseases, but RCM is stiff with usually normal thickness and big atria, while HCM is stiff because it is thick.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-arvc-fibrofatty", "ARVC: when RV muscle turns to fat and scar", "In ARVC, defective desmosomes let right-ventricular myocytes detach and die; fibro-fatty tissue replaces them, so the RV dilates and fails, and the scattered surviving muscle conducts late and unevenly — epsilon waves and catecholamine-triggered VT.", [
      S("idea", "The idea", "<p><strong>Desmosomes</strong> are the rivets that hold heart muscle cells together. In <strong>ARVC</strong> (autosomal dominant), mutated desmosomal proteins let myocytes <strong>detach and die (apoptosis)</strong>. Fibrous and fatty tissue moves in to fill the gaps.</p><p>Two problems follow. <strong>Mechanical:</strong> fat and scar don't contract, so the RV dilates and moves abnormally → right-sided HF. <strong>Electrical:</strong> the surviving strands of muscle are scattered between fat and fibrous tissue, so they are excited <strong>late</strong> — the <strong>epsilon wave</strong> — and the patchy path favors <strong>VT</strong>.</p><p>Exercise makes it worse: the <strong>catecholamine surge</strong> of exertion often precipitates the arrhythmia. ARVC is the <strong>2nd most common cause of sudden death in athletes</strong>.</p>"),
      S("chain", "Cause → effect", chain([
        "Desmosomal protein mutation (autosomal dominant) → myocyte detachment and apoptosis.",
        "Myocytes replaced by fibro-fatty tissue, mainly in the RV.",
        "Non-contracting RV wall → RV dilation and wall motion abnormalities → right-sided HF (JVD, edema, ascites).",
        "Surviving myocyte strands scattered in fat/fibrosis → delayed excitation → epsilon wave at the end of the QRS (V1).",
        "Patchy conduction + exercise catecholamines → VT → sudden death."
      ]) + Tbl(["Phase", "What the patient shows"], [
        ["Concealed", "Asymptomatic"],
        ["Electrical", "Palpitations or syncope (arrhythmias)"],
        ["Diffuse", "Right-sided heart failure"]
      ]) + HY("ARVC: desmosomes fail → fibro-fatty RV → late, patchy conduction (epsilon wave, VT) + RV failure; exercise catecholamines trigger it.")),
      S("bedside", "Why it matters clinically", "<p><strong>Who:</strong> often diagnosed in the 2nd–3rd decade; an athlete with palpitations or syncope during exertion.</p><p><strong>EKG:</strong> suggestive but nonspecific (50% normal at presentation): PVCs, QRS prolongation, VT, bundle branch blocks, T-wave inversions, <strong>epsilon wave</strong>.</p><p><strong>Imaging:</strong> echo (test of choice) shows an enlarged RV with wall motion abnormalities, possibly fat in the RV wall, and a <strong>normal LV until late</strong>. Cardiac MRI is the best study to identify the fibro-fatty infiltrate.</p><p><strong>Treatment follows the mechanism:</strong> activity restriction (remove the catecholamine trigger), <strong>beta-blockers first line</strong> (block catecholamine effect), ICD for secondary prevention after sustained ventricular arrhythmia, transplant as last resort.</p>" + clar("beta-blockers blunt the heart's response to catecholamines, which is why they fit a disease whose arrhythmias are provoked by exercise-related catecholamine release.")),
      S("traps", "Common traps", traps([
        "<strong>“ARVC is a left ventricular disease.”</strong> It targets the RV; the LV is normal until later stages.",
        "<strong>“ARVC and HCM share the same gene defect.”</strong> Both are autosomal dominant, but HCM is sarcomeric and ARVC is desmosomal.",
        "<strong>“A normal first EKG rules out ARVC.”</strong> Half of patients have a normal EKG at presentation.",
        "<strong>“HCM and ARVC are equally common causes of athlete SCD.”</strong> HCM is the leading cause; ARVC is the 2nd."
      ]))
    ], [
      Q("idea", "What happens to RV myocytes in ARVC?", ["Desmosomal defects cause detachment and apoptosis, and fibro-fatty tissue replaces them", "Sarcomere mutations make them hypertrophy", "Amyloid deposits stiffen them", "Viral infection inflames them transiently"], 0, "Mutations in desmosomal proteins cause myocyte detachment and apoptosis, followed by fibro-fatty replacement."),
      Q("chain", "Why does an epsilon wave appear in ARVC?", ["Surviving myocyte strands scattered among fat and fibrosis are excited late", "The atria depolarize after the ventricles", "The LV septum is thickened", "Pericardial fluid creates notches"], 0, "Epsilon waves are caused by delayed excitation of myocyte strands scattered between fibrous and fatty tissue."),
      Q("chain", "An ARVC patient sprints in a race. What does the lecture predict about arrhythmia risk?", ["It rises — exercise catecholamine release often precipitates VT", "It falls — exercise stabilizes conduction", "It is unchanged", "Only bradycardia can occur"], 0, "VT in ARVC is often precipitated by catecholamine release during exercise."),
      Q("chain", "Fibro-fatty tissue replaces RV muscle. Which heart failure pattern follows?", ["Right-sided: JVD, peripheral edema, ascites", "Left-sided: frothy sputum and rales first", "None, because fat contracts normally", "Isolated LVOT obstruction"], 0, "Fat and scar don't contract, so the RV dilates and fails, backing pressure into the systemic veins."),
      Q("bedside", "Why are beta-blockers first-line in ARVC?", ["They blunt the catecholamine effect that triggers ventricular arrhythmias", "They reverse fibro-fatty replacement", "They increase RV contractility", "They dissolve RV thrombus"], 0, "Exercise catecholamines precipitate VT; beta-blockers are the first-line anti-arrhythmic drugs, alongside activity restriction."),
      Q("bedside", "Echo shows an enlarged RV with wall motion abnormalities. Which study best identifies the fibro-fatty infiltrate?", ["Cardiac MRI", "Chest x-ray", "BNP", "Exercise stress test"], 0, "Cardiac MRI is the best study to identify fibro-fatty infiltrates in a patient with RV findings on echo."),
      Q("traps", "A 24-year-old with exertional palpitations has a normal EKG. Why can ARVC not be excluded?", ["About 50% of ARVC patients have a normal EKG at presentation", "ARVC never changes the EKG", "ARVC is diagnosed only by EKG", "A normal EKG proves the LV is involved"], 0, "The EKG is suggestive but nonspecific; half are normal at presentation, though findings appear over time."),
      Q("traps", "Which pairing of gene defect and disease is correct?", ["Desmosomal protein → ARVC; sarcomere → HCM", "Sarcomere → ARVC; desmosomal → HCM", "Dystrophin → ARVC; desmosomal → DCM", "Desmosomal → RCM; sarcomere → myocarditis"], 0, "Both are autosomal dominant genetic cardiomyopathies, but ARVC is desmosomal and HCM is sarcomeric.")
    ]),

    // ------------------------------------------------------------------
    D("cmp-catecholamine-stunning", "Tako-tsubo: a catecholamine surge that stuns the apex", "A sudden emotional or physical stress floods the heart with catecholamines, causing coronary spasm and transient apical dysfunction with a hypercontracting base — it looks exactly like a STEMI, but the coronaries are clear and the LV recovers.", [
      S("idea", "The idea", "<p>Catecholamines (adrenaline and its relatives) normally make the heart beat faster and stronger. A huge, sudden surge — after acute emotional or psychological distress — overshoots.</p><p>The lecture's mechanism: the <strong>surge causes coronary artery spasm</strong>, and the LV develops <strong>impaired contraction of the apex</strong> with <strong>hypercontraction of the base</strong>. The base squeezes hard while the apex balloons out, giving the shape of a Japanese octopus pot — the <em>tako-tsubo</em>.</p><p>Because nothing is permanently blocked, the dysfunction is <strong>transient</strong>: survivors usually recover LV function within about 4 weeks.</p>"),
      S("chain", "Cause → effect", chain([
        "Acute emotional or psychological stress → catecholamine surge.",
        "Coronary artery spasm → impaired apical contractility; base hypercontracts.",
        "Apical ballooning → acute LV dysfunction; may cause cardiogenic shock or acute HF.",
        "Chest pain, EKG changes, and elevated troponin → treated first as a STEMI.",
        "Cardiac cath: LV wall motion abnormalities but no significant CAD.",
        "Stress and catecholamines subside → LV recovers, usually within 4 weeks."
      ]) + Tbl(["", "STEMI", "Tako-tsubo"], [
        ["Trigger", "Plaque rupture / CAD", "Emotional or psychological stress → catecholamines"],
        ["EKG and troponin", "Abnormal / elevated", "Abnormal / elevated (looks the same)"],
        ["Cath", "Significant coronary occlusion", "<strong>No significant CAD</strong>; apical ballooning"],
        ["Course", "Infarcted muscle", "<strong>Transient</strong> — recovers in ~4 weeks"]
      ]) + HY("Tako-tsubo: catecholamine surge → spasm → apical ballooning; STEMI picture with clean coronaries; recovers.")),
      S("bedside", "Why it matters clinically", "<p>Names to recognize: <strong>stress-induced CM</strong>, <strong>broken-heart syndrome</strong>.</p><p>In the acute setting you <strong>treat it as a STEMI</strong> because the clinical picture, EKG, and troponin all point there; the cath is what reveals no significant CAD. Some patients need intensive care for cardiogenic shock or acute HF.</p><p>Once stable, <strong>benzodiazepines</strong> (diazepam, lorazepam) may be used to reduce stress and so <strong>decrease catecholamine release</strong> — treating the trigger in the chain. Recurrence risk is about <strong>2% per year</strong>; some specialists prefer lifelong beta-blockers, though efficacy is unknown.</p><p>The same catecholamine idea runs through the lecture: exercise catecholamines provoke VT in ARVC and worsen LVOT obstruction in HCM; prolonged oral beta-agonist (terbutaline) tocolysis is a PPCM risk factor.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“Clean coronaries mean nothing is wrong with the heart.”</strong> The LV still has real, possibly severe, wall motion abnormalities; shock and acute HF can occur.",
        "<strong>“Skip STEMI treatment if you suspect tako-tsubo.”</strong> Acutely it is treated as a STEMI; only the cath reveals the difference.",
        "<strong>“The whole ventricle stops working.”</strong> The apex is impaired while the base is hypercontractile.",
        "<strong>“Benzodiazepines treat the heart muscle directly.”</strong> They reduce stress, which decreases catecholamine release — the trigger."
      ]))
    ], [
      Q("idea", "What triggers tako-tsubo cardiomyopathy?", ["A catecholamine surge after acute emotional or psychological stress", "Plaque rupture in the LAD", "A desmosomal gene mutation", "Viral infection of the myocardium"], 0, "Tako-tsubo is precipitated by acute emotional or psychological distress; the catecholamine surge causes coronary spasm."),
      Q("chain", "Which LV wall-motion pattern results from the catecholamine surge?", ["Impaired apical contraction with a hypercontractile base (apical ballooning)", "Hypercontractile apex with an akinetic base", "Uniform dilation with EF ≤ 40%", "Asymmetric septal thickening"], 0, "The classic apical variant shows apical akinesis with hyperdynamic basal segments, resembling the octopus pot."),
      Q("bedside", "A woman develops crushing chest pain, ST changes, and elevated troponin hours after her husband's funeral. What is the first management approach?", ["Treat as a STEMI; cath will clarify", "Discharge with a benzodiazepine", "Start digoxin and diuretics only", "Order a cardiac MRI before any treatment"], 0, "The clinical picture, EKG, and troponin mimic a STEMI, so it is treated as one acutely; cath shows wall motion abnormalities without significant CAD."),
      Q("chain", "Cardiac catheterization is performed in tako-tsubo. Predict the findings.", ["LV wall motion abnormalities with no significant CAD", "Complete occlusion of the LAD", "Normal LV wall motion and normal coronaries", "Severe aortic stenosis"], 0, "The cath visualizes the apical wall motion abnormality but no significant coronary artery disease."),
      Q("bedside", "Why might a benzodiazepine be used once a tako-tsubo patient is stable?", ["To reduce stress and decrease catecholamine release", "To dissolve coronary thrombus", "To increase contractility of the apex", "To reduce LVOT obstruction"], 0, "Diazepam or lorazepam reduce stress, which decreases the catecholamine release that drives the condition."),
      Q("chain", "The catecholamine surge resolves. What happens to LV function in survivors?", ["It typically recovers within about 4 weeks", "It is permanently lost like an infarct", "It progresses to restrictive physiology", "It converts to HCM"], 0, "The dysfunction is transient; survivors typically recover LV function within 4 weeks."),
      Q("traps", "A student says tako-tsubo is harmless because the coronaries are normal. What's the correction?", ["Acute LV dysfunction can cause cardiogenic shock or acute HF needing intensive care", "The coronaries are always severely blocked", "Tako-tsubo never recurs or causes symptoms", "It is always fatal"], 0, "Some patients develop cardiogenic shock and acute HF despite clean coronaries; recurrence risk is about 2% per year.")
    ])
  ]);
}());
